    {
      "fact_id": "fcs_page_x_marks_visible",
      "state": "not_seen",
      "evidence_note": "Since the FCS page is not visible, no X marks are visible."
    },
    {
      "fact_id": "bit_root_page_visible",
      "state": "seen",
      "evidence_note": "The Right DDI clearly displays the 'BIT FAILURES' page, which serves as the root page for Built-In Test failures."
    },
    {
      "fact_id": "fcsmc_page_visible",
      "state": "not_seen",
      "evidence_note": "The FCS-MC subpage is not visible. The Right DDI shows the BIT FAILURES root page which lists 'FCS-MC' as a category with a 'GO' status, but the detailed FCS-MC page with MC1/MC2/FCSA/FCSB rows is not displayed."
    },
    {
      "fact_id": "fcsmc_intermediate_result_visible",
      "state": "not_seen",
      "evidence_note": "The FCS-MC page is not visible, so no intermediate results are seen."
    },
    {
      "fact_id": "fcsmc_in_test_visible",
      "state": "not_seen",
      "evidence_note": "The FCS-MC page is not visible, so no 'IN TEST' status is seen."
    },
    {
      "fact_id": "fcsmc_final_go_result_visible",
      "state": "not_seen",
      "evidence_note": "The FCS-MC page is not visible. While the BIT FAILURES root page shows 'FCS-MC GO', this is a summary status, not the final result on the FCS-MC subpage."
    },
    {
      "fact_id": "hsi_page_visible",
      "state": "seen",
      "evidence_note": "The AMPCD displays a navigation map page, which is a form of HSI/POS page."
    },
    {
      "fact_id": "hsi_map_layer_visible",
      "state": "seen",
      "evidence_note": "The AMPCD clearly shows a colored topographic map background with terrain features, rivers, and roads."
    },
    {
      "fact_id": "ins_grnd_alignment_text_visible",
      "state": "not_seen",
      "evidence_note": "No 'GRND' alignment text or countdown timer is visible on any display. The Left DDI shows 'INS ATT' and 'INS DEGD' on the TAC page, but not the specific GRND alignment block."
    },
    {
      "fact_id": "ins_ok_text_visible",
      "state": "not_seen",
      "evidence_note": "No 'OK' text associated with INS alignment is visible."
    }
  ]
}
